cat > src/text.js <<'EOF'
export function slugify(text) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string')
  }
  return text
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '')
}
EOF
cat > test/text.test.js <<'EOF'
import test from 'node:test'
import assert from 'node:assert/strict'
import { slugify } from '../src/text.js'

test('slugify strips diacritics and punctuation', () => {
  assert.equal(slugify('Crème Brûlée!'), 'creme-brulee')
})

test('slugify trims and collapses separators', () => {
  assert.equal(slugify('  --Hello,   World--  '), 'hello-world')
  assert.equal(slugify('a___b...c'), 'a-b-c')
})

test('slugify returns empty string for empty or symbol-only input', () => {
  assert.equal(slugify(''), '')
  assert.equal(slugify('!!!'), '')
})

test('slugify throws TypeError for non-strings', () => {
  assert.throws(() => slugify(42), TypeError)
  assert.throws(() => slugify(undefined), TypeError)
})
EOF
npm test 2>&1 | grep -E "^# (pass|fail)"
