export function truncate(text, max) {
  assertText(text)
  assertPositiveInteger(max, 'max')
  if (text.length <= max) return text
  const limit = max - 1
  // Look one character past the limit so a word ending exactly at it counts as whole.
  const window = text.slice(0, limit + 1)
  const boundary = window.search(/\s\S*$/)
  const cut = boundary === -1 ? '' : window.slice(0, boundary).trimEnd()
  return (cut === '' ? text.slice(0, limit) : cut) + '…'
}
EOF
cat >> test/text.test.js <<'EOF'

test('truncate returns text unchanged when it fits', () => {
  assert.equal(truncate('hello world', 20), 'hello world')
  assert.equal(truncate('hello world', 11), 'hello world')
})

test('truncate cuts at a word boundary and appends an ellipsis', () => {
  assert.equal(truncate('the quick brown fox', 12), 'the quick…')
  assert.equal(truncate('the quick brown fox', 10), 'the quick…')
  assert.equal(truncate('the quick brown fox', 9), 'the…')
})

test('truncate never exceeds max and ends with an ellipsis', () => {
  const text = 'the quick brown fox jumps over the lazy dog'
  for (let max = 1; max < text.length; max++) {
    const out = truncate(text, max)
    assert.ok(out.length <= max, `max ${max}: ${out}`)
    assert.ok(out.endsWith('…'))
  }
})

test('truncate hard-cuts when no word boundary fits', () => {
  assert.equal(truncate('extraordinary claims', 6), 'extra…')
  assert.equal(truncate('abcdef', 1), '…')
})

test('truncate throws TypeError for invalid arguments', () => {
  for (const max of [0, -1, 1.5, NaN, '10', undefined]) {
    assert.throws(() => truncate('a b', max), TypeError)
  }
  assert.throws(() => truncate(42, 10), TypeError)
})
EOF
